package com.aitrading.document;import com.aitrading.ai.AiFailure;import com.aitrading.api.*;import com.aitrading.auth.UserPrincipal;import com.aitrading.strategy.StrategyService;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/documents") public class DocumentController{private final DocumentService service;public DocumentController(DocumentService s){service=s;}@GetMapping public List<DocumentService.Document> list(@AuthenticationPrincipal UserPrincipal u){return service.list(u);}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public DocumentService.Saved create(@AuthenticationPrincipal UserPrincipal u,@RequestParam String requestId,@RequestParam Integer expectedVersion,@RequestParam String title,@RequestPart("file") MultipartFile file){return service.upload(u,null,requestId,expectedVersion,title,file);}@PostMapping(value="/{id}/versions",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public DocumentService.Saved version(@AuthenticationPrincipal UserPrincipal u,@PathVariable String id,@RequestParam String requestId,@RequestParam Integer expectedVersion,@RequestParam String title,@RequestPart("file") MultipartFile file){return service.upload(u,StrategyService.id(id),requestId,expectedVersion,title,file);}public record DeleteRequest(Integer expectedVersion){}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserPrincipal u,@PathVariable String id,@RequestBody DeleteRequest body){service.delete(u,StrategyService.id(id),body.expectedVersion()==null?-1:body.expectedVersion());return ResponseEntity.noContent().build();}public record Query(String question){}@PostMapping("/rag")public DocumentService.Answer ask(@AuthenticationPrincipal UserPrincipal u,@RequestBody Query body){return service.ask(u,body.question());}@ExceptionHandler(AiFailure.class)public ResponseEntity<?> unavailable(HttpServletRequest request,AiFailure failure){return ResponseEntity.status(503).body(Map.of("code",failure.code().name(),"requestId",ApiErrors.requestId(request)));}}
